import { z } from 'zod';
import { Activity,ArrowRight,ArrowUpRight,BarChart3,Bell,CalendarDays,Check,CheckCircle2,ChevronLeft,ChevronRight,ChevronsUpDown,Clock,CloudUpload,ExternalLink,FileText,FolderOpen,ImagePlus,Instagram,Linkedin,Layers,LayoutDashboard,Link2,Loader2,LogOut,Menu,MessageCircle,MoreHorizontal,Pause,Play,Plus,Search,Settings,ShieldCheck,Sparkles,Users,WandSparkles,X,Zap } from 'lucide-react';
